pub fn pairwise_addition(a: Vec<i32>) -> Vec<i32> {
    // Ensure input length is even
    assert!(
        a.len() % 2 == 0,
        "Input vector length must be even, got {}",
        a.len()
    );

    // Pre-allocate output vector with half the length of the input
    let mut result = Vec::with_capacity(a.len() / 2);

    // Sum each consecutive pair
    for chunk in a.chunks(2) {
        // chunk has exactly two elements because we asserted even length
        result.push(chunk[0] + chunk[1]);
    }

    result
}

